INSERT INTO diagnosis_questions (question_text, sort_order) SELECT '果物の香りなら、どちらが好み？', 11 WHERE NOT EXISTS (SELECT 1 FROM diagnosis_questions WHERE question_text = '果物の香りなら、どちらが好み？');
INSERT INTO diagnosis_choices (question_id, choice_text) SELECT q.id, 'みずみずしく、軽やかな香り' FROM diagnosis_questions q WHERE q.question_text = '果物の香りなら、どちらが好み？' AND NOT EXISTS (SELECT 1 FROM diagnosis_choices c WHERE c.question_id = q.id AND c.choice_text = 'みずみずしく、軽やかな香り');
INSERT INTO choice_tags (choice_id, tag_id, weight) SELECT c.id, t.id, 2 FROM diagnosis_choices c JOIN diagnosis_questions q ON q.id = c.question_id CROSS JOIN tags t WHERE q.question_text = '果物の香りなら、どちらが好み？' AND c.choice_text = 'みずみずしく、軽やかな香り' AND t.name = 'フルーティー' AND NOT EXISTS (SELECT 1 FROM choice_tags ct WHERE ct.choice_id = c.id AND ct.tag_id = t.id);
